import java.util.Arrays;
import java.util.IntSummaryStatistics;

/**
 * TASK: Summarise an int array in ONE pass using IntStream summary statistics.
 *
 * summaryLine(scores) returns a report string in exactly this shape:
 *     "count=3 min=70 max=90 sum=245 avg=81.67"
 * The average is formatted with exactly two decimals using Locale.US.
 *
 * range(scores) returns max - min.
 *
 * EDGE CASE: for an empty array, summaryLine returns
 *     "count=0 min=0 max=0 sum=0 avg=0.00"
 * and range returns 0. (An IntSummaryStatistics built from no values reports
 * min = Integer.MAX_VALUE, so you must handle the empty case yourself.)
 */
public class ScoreSummary {

    public static String summaryLine(int[] scores) {
        if (scores.length == 0) {
            return "count=0 min=0 max=0 sum=0 avg=0.00";
        }
        IntSummaryStatistics stats = Arrays.stream(scores).summaryStatistics();
        return String.format(java.util.Locale.US,
                "count=%d min=%d max=%d sum=%d avg=%.2f",
                stats.getCount(), stats.getMin(), stats.getMax(),
                stats.getSum(), stats.getAverage());
    }

    public static int range(int[] scores) {
        if (scores.length == 0) {
            return 0;
        }
        IntSummaryStatistics stats = Arrays.stream(scores).summaryStatistics();
        return stats.getMax() - stats.getMin();
    }
}
